   253→  {
   254→    try {
   255→      MessageDigest md = MessageDigest.getInstance("SHA-1");
   256→      byte[] fieldNameBytes = StringUtils.toUtf8(Joiner.on(",").join(fieldNames));
   257→      byte[] sha1 = md.digest(StringUtils.toUtf8(fnAggregate + fnReset + fnCombine));
