    20→package org.apache.druid.java.util.common.parsers;
    21→
    22→import com.google.common.base.Function;
    23→import org.mozilla.javascript.Context;
    24→import org.mozilla.javascript.ContextFactory;
    25→import org.mozilla.javascript.ScriptableObject;
    26→
    27→import java.util.List;
    28→import java.util.Map;
    29→
    30→/**
    31→ */
    32→public class JavaScriptParser implements Parser<String, Object>
    33→{
    34→  private static Function<Object, Object> compile(String function)
    35→  {
    36→    final ContextFactory contextFactory = ContextFactory.getGlobal();
    37→    final Context context = contextFactory.enterContext();
    38→    context.setOptimizationLevel(9);
    39→
    40→    final ScriptableObject scope = context.initStandardObjects();
    41→
    42→    final org.mozilla.javascript.Function fn = context.compileFunction(scope, function, "fn", 1, null);
    43→    Context.exit();
    44→
    45→    return new Function<Object, Object>()
    46→    {
    47→      @Override
    48→      public Object apply(Object input)
    49→      {
    50→        // ideally we need a close() function to discard the context once it is not used anymore
    51→        Context cx = Context.getCurrentContext();
    52→        if (cx == null) {
    53→          cx = contextFactory.enterContext();
    54→        }
    55→
    56→        final Object res = fn.call(cx, scope, scope, new Object[]{input});
    57→        return res != null ? Context.toObject(res, scope) : null;
    58→      }
    59→    };
    60→  }
    61→
    62→  private final Function<Object, Object> fn;
    63→
    64→  public JavaScriptParser(
    65→      final String function
    66→  )
    67→  {
    68→    this.fn = compile(function);
    69→  }
    70→
    71→  @Override
    72→  public Map<String, Object> parseToMap(String input)
    73→  {
    74→    try {
    75→      final Object compiled = fn.apply(input);
    76→      if (!(compiled instanceof Map)) {
    77→        throw new ParseException("JavaScript parsed value must be in {key: value} format!");
    78→      }
    79→
    80→      return (Map) compiled;
    81→    }
    82→    catch (Exception e) {
    83→      throw new ParseException(e, "Unable to parse row [%s]", input);
    84→    }
    85→  }
    86→
