    88→  public void setFieldNames(Iterable<String> fieldNames)
    89→  {
    90→    throw new UnsupportedOperationException();
    91→  }
    92→
    93→  @Override
    94→  public List<String> getFieldNames()
    95→  {
    96→    throw new UnsupportedOperationException();
    97→  }
    98→}
